async function importSession(text,name){const duplicate=sessions.find(x=>x.text===text);if(duplicate){setActive(duplicate.id);message('Duplicate log recognized. Existing session selected; review observations were not counted twice.');return duplicate;}const log=E.parseLog(text,name),id='session-'+Date.now()+'-'+(++sessionCounter),item={id,name,text,log,calibration:'',notes:'',excluded:false};sessions.push(item);learning.push({sessionId:id,date:new Date().toISOString(),title:'Historical log imported',detail:`${log.data.length} parsed rows and ${log.headers.length} channels. ${log.rejectedRows} malformed rows excluded. Calibration match and comparable operating conditions are not yet established.`});setActive(id);await persistSessionStore();message(name+' imported once and available across workspaces.');return item;}
