function plotBounds(){let rows=reviewRows;const start=$('logStart').value.trim(),end=$('logEnd').value.trim();if(start&&end&&+start>+end)throw Error('Plot start must precede end');if(start||end)rows=rows.filter(r=>(!start||r.time>=+start)&&(!end||r.time<=+end));const x=$('logXAxis').value,ys=rows.flatMap(r=>[$('showActual').checked?r.bp:null,$('showCommand').checked?r.cmd:null]).filter(Number.isFinite);const comp=sessions.find(x=>x.id===$('comparisonSession').value);if(comp&&!$('logYMin').value.trim()&&!$('logYMax').value.trim()){const extra=S.filtered(comp.log,getLogOptions(comp));ys.push(...extra.rows.map(r=>r.bp));}let xmin=rows.reduce((a,r)=>Math.min(a,r[x]),Infinity),xmax=rows.reduce((a,r)=>Math.max(a,r[x]),-Infinity),ymin=$('logYMin').value.trim()?+$('logYMin').value:ys.reduce((a,b)=>Math.min(a,b),Infinity),ymax=$('logYMax').value.trim()?+$('logYMax').value:ys.reduce((a,b)=>Math.max(a,b),-Infinity);if(rows.length&&ys.length&&ymin>ymax)throw Error('Y minimum must not exceed Y maximum');if(ymin===ymax){ymin-=1;ymax+=1;}if(xmin===xmax)xmax=xmin+1;if(!$('logYMin').value.trim())ymin-=1;if(!$('logYMax').value.trim())ymax+=1;return{rows,x,xmin,xmax,ymin,ymax};}
