const row=reviewRows[selectedFrame];if(row&&chartRows.includes(row)){svg+=`<line id="inspectionCursor" x1="${X(row[b.x])}" x2="${X(row[b.x])}" y1="${T}" y2="${height-B}" stroke="var(--text)" stroke-dasharray="5 4"/>`;for(const[k,show,color]of [['bp',$('showActual').checked,$('actualColor').value],['cmd',$('showCommand').checked,$('commandColor').value]])if(show)svg+=`<circle data-cursor-point="${k}" cx="${X(row[b.x])}" cy="${Y(row[k])}" r="5" fill="${color}" stroke="var(--surface)" stroke-width="2"/>`;}
