function drawLogAnalytics(){const values=reviewRows.map(x=>x.bp-x.cmd),bins=S.histogram(values,20),max=Math.max(1,...bins.map(x=>x.count));$('errorHistogram').innerHTML=bins.length?'<svg viewBox="0 0 450 210" role="img" aria-label="Boost error histogram">'+bins.map((b,j)=>`<rect data-bin="${j}" x="${30+j*19}" y="${180-b.count/max*145}" width="17" height="${b.count/max*145}" fill="var(--accent)"><title>${fmt(b.min)} to ${fmt(b.max)} PSI: ${b.count} samples</title></rect>`).join('')+`<text x="25" y="202" fill="var(--muted)" font-size="11">${fmt(bins[0].min)} to ${fmt(bins.at(-1).max)} PSI error</text></svg>`:'No eligible data';const sample=reviewRows.filter((_,j)=>j%Math.max(1,Math.ceil(reviewRows.length/2000))===0),xmin=sample.reduce((a,r)=>Math.min(a,r.rpm),Infinity),xmax=sample.reduce((a,r)=>Math.max(a,r.rpm),-Infinity),ymin=Math.min(0,...sample.map(r=>r.bp-r.cmd)),ymax=Math.max(1,...sample.map(r=>r.bp-r.cmd));$('errorScatter').innerHTML=sample.length?'<svg viewBox="0 0 450 210" role="img" aria-label="RPM versus boost error scatter">'+sample.map(r=>`<circle data-source-index="${r.sourceIndex}" cx="${30+(r.rpm-xmin)/(xmax-xmin||1)*380}" cy="${180-(r.bp-r.cmd-ymin)/(ymax-ymin||1)*150}" r="2" fill="var(--accent)"><title>${fmt(r.rpm,0)} RPM; ${fmt(r.bp-r.cmd)} PSI error</title></circle>`).join('')+'<text x="25" y="202" fill="var(--muted)" font-size="11">RPM → simultaneous error</text></svg>':'No eligible data';$('errorScatter').querySelectorAll('[data-source-index]').forEach(n=>n.onclick=()=>{$('frameSlider').value=reviewRows.findIndex(r=>r.sourceIndex===+n.dataset.sourceIndex);inspectFrame();});$('errorHistogram').querySelectorAll('[data-bin]').forEach(n=>n.onclick=()=>{const b=bins[+n.dataset.bin],ix=reviewRows.findIndex(r=>r.bp-r.cmd>=b.min&&r.bp-r.cmd<=b.max);if(ix>=0){$('frameSlider').value=ix;inspectFrame();message(`${b.count} selected-bin samples; cursor moved to first contributor. ${fmt(b.min)}–${fmt(b.max)} PSI error.`);}});}
