function renderOverlays(){document.querySelectorAll('.operating-cell').forEach(n=>n.classList.remove('operating-cell'));const row=reviewRows[selectedFrame];if(!row){$('operatingReadout').textContent='Choose a historical log and an eligible sample in Log review.';return;}const item=sessions.find(x=>x.id===activeSession),raw=review?.data[row.sourceIndex],hzIx=review?E.index(review,$('map_hz').value):-1,paIx=review?E.index(review,'PA'):-1,loggedPa=paIx>=0?raw[paIx]:NaN,pa=Number.isFinite(loggedPa)&&loggedPa>0&&loggedPa<2?loggedPa:+$('referencePa').value;const t=state[kind].source;let note;try{const[rl,rh,rw]=E.bracket(t.rpm,row.rpm),axis=kind==='mpr'?pa:row.cmd,[cl,ch,cw]=E.bracket(t.axis,axis);for(const r of new Set([rl,rh]))for(const c of new Set([cl,ch]))for(const id of ['sourceGrid','proposedGrid'])$(id).querySelector(`tbody tr:nth-child(${r+1}) td:nth-child(${c+2})`)?.classList.add('operating-cell');note=`Recorded ${fmt(row.rpm,0)} RPM; ${kind==='mpr'?'atmosphere '+fmt(pa,3)+' bar'+(Number.isFinite(loggedPa)&&loggedPa>0&&loggedPa<2?' from log':' from selected reference (not logged)'):'logged command '+fmt(row.cmd)+' PSI'}; RPM interpolation ${(rw*100).toFixed(1)}%, column interpolation ${(cw*100).toFixed(1)}%.`;}catch{note='Operating point is outside the loaded table axes; no extrapolated marker.';}$('operatingReadout').textContent=`${item?.name??review?.name} · ${item?.calibration||'Calibration not recorded'} · ${fmt(row.time,3)} s. ${note}`;if(hzIx>=0&&Number.isFinite(raw[hzIx])){let closest=0;for(let j=0;j<state.afm.length;j++)if(Math.abs(state.afm[j].hz-raw[hzIx])<Math.abs(state.afm[closest].hz-raw[hzIx]))closest=j;$('afmPreview').querySelector(`[data-ec="${closest}"]`)?.classList.add('operating-cell');}}
