const afmSourceTools=document.createElement('details');afmSourceTools.innerHTML=`<summary>Edit source airflow curve / indices</summary><p>Enter the source frequency and g/s values as two rows. Editing frequency points is explicit; protects retained coordinates and prevents removal of locked frequencies.</p><textarea id="afmSourceEdit" rows="4" aria-label="Editable source airflow rows"></textarea><div class="actions"><button id="applyAfmSource">Apply edited source</button><button id="regridAfmSource" class="secondary">Resample using first-row frequencies</button><button id="restoreAfmImport" class="secondary">Restore last AFM import</button></div>`;$('afmPreview').after(afmSourceTools);
function sourceAfmText(){return['Frequency (Hz)\t'+state.afm.map(x=>x.hz).join('\t'),'Mass flow (g/s)\t'+state.afm.map(x=>x.flow).join('\t')].join('\n');}$('afmSourceEdit').value=sourceAfmText();
function protectAfmSource(next){for(const x of state.afm.filter(x=>x.protect))if(!next.some(n=>n.hz===x.hz))throw Error('Edited grid removes protected frequency '+x.hz+' Hz');return next.map(x=>({...x,protect:state.afm.find(y=>y.hz===x.hz)?.protect??false}));}
$('applyAfmSource').onclick=action(()=>{const next=protectAfmSource(E.parseAfm($('afmSourceEdit').value));checkpoint();state.afm=next;afmResult=null;$('baselineConfirm').checked=false;markAfmDirty();renderAfm();message('AFM source changed. Baseline confirmation cleared.');});$('regridAfmSource').onclick=action(()=>{const first=$('afmSourceEdit').value.split(/\r?\n/)[0].split('\t'),freqs=first.map(E.numeric).filter(Number.isFinite);const old={rpm:[0],axis:state.afm.map(x=>x.hz),values:[state.afm.map(x=>x.flow)],protect:[state.afm.map(x=>x.protect)]},grid=S.regrid(old,[0],freqs);checkpoint();state.afm=protectAfmSource(freqs.map((hz,j)=>({hz,flow:grid.values[0][j]})));afmResult=null;$('baselineConfirm').checked=false;markAfmDirty();$('afmSourceEdit').value=sourceAfmText();renderAfm();message('Airflow source resampled. Review source/calibration match.');});$('restoreAfmImport').onclick=action(()=>{checkpoint();state.afm=clone(lastImports.afm);afmResult=null;$('baselineConfirm').checked=false;markAfmDirty();$('afmSourceEdit').value=sourceAfmText();renderAfm();});
function recordState(){return{frame:currentFrame(),afmSource:clone(state.afm),controls:inputsState()};}
const previousCheckpoint=checkpoint;checkpoint=function(){if(journalBusy)return;const before=recordState(),epoch=window.TuneLabProjectEpoch??0;previousCheckpoint();queueMicrotask(()=>{if(epoch!==(window.TuneLabProjectEpoch??0))return;const after=recordState();if(JSON.stringify(before.frame)===JSON.stringify(after.frame)&&JSON.stringify(before.afmSource)===JSON.stringify(after.afmSource))return;const entry={id:'edit-'+Date.now()+'-'+journal.length,date:new Date().toISOString(),page:currentPage(),kind,table:currentPage()==='afm'?'Airflow meter calibration':currentPage()==='gears'?'Boost by gear':state[kind].source.name,before,after,disabled:false};journal.push(entry);renderHistory();});};
function entryDelta(entry){if(entry.page==='afm'){const b=entry.before.frame.afm??entry.before.afmSource.map(x=>({...x,proposed:x.flow})),a=entry.after.frame.afm??entry.after.afmSource.map(x=>({...x,proposed:x.flow}));if(JSON.stringify(b.map(x=>x.hz))!==JSON.stringify(a.map(x=>x.hz)))return null;return S.changes([b.map(x=>x.proposed)],[a.map(x=>x.proposed)]).map(x=>({...x,coordinate:a[x.c].hz+' Hz'}));}if(entry.page==='gears')return null;const b=entry.before.frame[entry.kind],a=entry.after.frame[entry.kind];if(JSON.stringify(b.source.rpm)!==JSON.stringify(a.source.rpm)||JSON.stringify(b.source.axis)!==JSON.stringify(a.source.axis)||JSON.stringify(b.controls)!==JSON.stringify(a.controls))return null;const bv=b.proposal?.values??b.source.values,av=a.proposal?.values??a.source.values;return S.changes(bv,av).map(x=>({...x,coordinate:`${a.source.rpm[x.r]} RPM / ${a.source.axis[x.c]} index`}));}
function renderHistory(){$('historyList').innerHTML=journal.slice().reverse().map(x=>{let delta;try{delta=entryDelta(x);}catch{delta=null;}return`<article class="session-entry" id="history-${esc(x.id)}"><h3>${esc(x.table)} · ${esc(x.page)}</h3><p>${esc(x.date)} · ${x.disabled?'SELECTIVELY UNDONE':'Recorded operation'}</p><p>${delta?delta.length+' changed cells':'Structural, source or control change — use revision restoration'}</p><details><summary>Coordinates and before / after</summary><ul>${delta?delta.slice(0,100).map(d=>`<li>${esc(d.coordinate)}: ${fmt(d.before,5)} → ${fmt(d.after,5)}</li>`).join(''):'<li>Full before/after table state retained in this revision.</li>'}</ul></details><div class="actions"><button data-show-edit="${esc(x.id)}" class="secondary">Show in table</button><button data-undo-edit="${esc(x.id)}" class="secondary" ${x.disabled||!delta?.length?'disabled':''}>Undo this change only</button><button data-restore-edit="${esc(x.id)}" class="secondary">Restore state after this change</button></div></article>`;}).join('')||'<p>No recorded edits yet. New proposals and manual changes appear here.</p>';}
document.addEventListener('click',action(e=>{const n=e.target.closest('[data-show-edit],[data-undo-edit],[data-restore-edit]');if(!n)return;const id=n.dataset.showEdit??n.dataset.undoEdit??n.dataset.restoreEdit,entry=journal.find(x=>x.id===id);if(n.dataset.showEdit){goPage(entry.page);if(entry.page==='boost')switchKind(entry.kind);const delta=entryDelta(entry);if(delta?.length){const d=delta[0];selection={target:entry.page==='afm'?'airflow':'boost',a:[d.r,d.c],b:[d.r,d.c]};paintSelection();document.querySelector('.selected')?.scrollIntoView?.({block:'center',inline:'center'});}message('Located '+entry.table+' · '+entry.page+'.');return;}if(n.dataset.restoreEdit){if(!confirm('Restore the entire project editing state after this operation? Current work remains in history.'))return;const before=recordState();journalBusy=true;state.afm=clone(entry.after.afmSource);restoreFrame(clone(entry.after.frame));for(const [id,v]of Object.entries(entry.after.controls)){const control=$(id);if(!control||control.type==='file')continue;if(control.type==='checkbox')control.checked=!!v;else control.value=v;}journalBusy=false;const after=recordState();journal.push({id:'restore-'+Date.now(),date:new Date().toISOString(),page:entry.page,kind:entry.kind,table:'Revision restoration: '+entry.table,before,after,disabled:false});renderHistory();applyAppearance();renderReview();message('Revision restored as a new history operation. Recheck session/calibration match.');return;}
const delta=entryDelta(entry);if(!delta?.length)throw Error('This structural edit requires revision restoration');const before=recordState();if(entry.page==='afm'){if(!afmResult||afmDirty)throw Error('A fresh airflow proposal is required');const out=S.reverseChanges([afmResult.cells.map(x=>x.proposed)],delta);afmResult.cells.forEach((x,j)=>x.proposed=out[0][j]);refreshAfmDerived();renderAfm();}else{const b=state[entry.kind],reference=entry.after.frame[entry.kind];if(JSON.stringify(b.source.rpm)!==JSON.stringify(reference.source.rpm)||JSON.stringify(b.source.axis)!==JSON.stringify(reference.source.axis)||JSON.stringify(b.controls)!==JSON.stringify(reference.controls))throw Error('Axes or units changed after this edit. Use revision restoration.');if(b.dirty||!b.proposal)throw Error('A fresh proposal is required');b.proposal.values=S.reverseChanges(b.proposal.values,delta);const old=kind;switchKind(entry.kind,true);refreshBoostDerived();renderBoost();if(old!==entry.kind)switchKind(old);}entry.disabled=true;journal.push({id:'undo-'+Date.now(),date:new Date().toISOString(),page:entry.page,kind:entry.kind,table:'Selective undo: '+entry.table,before,after:recordState(),disabled:false});renderHistory();renderChanges();message('Selected operation reversed. Other non-overlapping changes retained.');}));
