let layoutPrefs={app:{theme:$('theme').value,accent:$('accent').value,experience:$('experience').value,compact:$('compact').checked,font:11,header:10,row:8,col:12},pages:{},panels:{}};
const layoutBar=document.createElement('details');layoutBar.className='panel layoutsettings';layoutBar.innerHTML=`<summary>Appearance & layout properties</summary><div class="formrow"><label>Apply appearance to<select id="appearanceScope"><option value="app">Entire app</option><option value="page">This page only</option></select></label><label>Cell font · px<input id="cellFont" type="number" min="9" max="24" value="11"></label><label>Header font · px<input id="headerFont" type="number" min="9" max="24" value="10"></label><label>Row padding · px<input id="rowPadding" type="number" min="2" max="24" value="8"></label><label>Column padding · px<input id="colPadding" type="number" min="3" max="40" value="12"></label><label>Columns<select id="fitColumns"><option value="content">Fit contents / scroll</option><option value="width">Fit available width</option></select></label></div><div class="actions"><button id="applyLayout">Apply layout settings</button><button id="resetPageLayout" class="secondary">Reset this page to app defaults</button><button id="exportLayout" class="secondary">Export preferences</button><label class="button secondary">Import preferences<input id="importLayout" type="file" accept=".json" hidden></label></div><p id="layoutInheritance" class="hint">Using app defaults. Drag panel corners to resize; use the panel buttons to collapse or expand.</p></details>`;sessionBar.after(layoutBar);
const oldAppearance=applyAppearance;let appearanceRestoring=false;
function appearanceTarget(){return currentPage()==='settings'?($('appearancePage')?.value??'boost'):currentPage();}
function effectivePrefs(){return currentPage()==='settings'&&$('appearanceScope').value==='app'?{...layoutPrefs.app}:{...layoutPrefs.app,...layoutPrefs.pages[appearanceTarget()]};}
function applyTableSizing(){for(const page of document.querySelectorAll('.page')){const p={...layoutPrefs.app,...layoutPrefs.pages[page.id]};page.style.setProperty('--cell-font',p.font+'px');page.style.setProperty('--header-font',p.header+'px');page.style.setProperty('--row-pad',(p.compact?Math.min(p.row,4):p.row)+'px');page.style.setProperty('--col-pad',(p.compact?Math.min(p.col,6):p.col)+'px');page.classList.toggle('fit-width',p.fit==='width');}$('layoutInheritance').textContent=currentPage()==='settings'&&$('appearanceScope').value==='app'?'Editing app defaults. Existing page overrides remain independent; select a page and This page only to edit or reset its overrides.':layoutPrefs.pages[appearanceTarget()]?'Page override active. Reset to inherit app defaults.':'Using app defaults.';}
applyAppearance=function(){oldAppearance();if(!appearanceRestoring){const picked={theme:$('theme').value,accent:$('accent').value,experience:$('experience').value,compact:$('compact').checked};if($('appearanceScope').value==='page')layoutPrefs.pages[appearanceTarget()]={...layoutPrefs.pages[appearanceTarget()],...picked};else layoutPrefs.app={...layoutPrefs.app,...picked};}applyTableSizing(effectivePrefs());try{localStorage.setItem('TuneLabLayoutV5',JSON.stringify(layoutPrefs));}catch{} };
function loadPagePrefs(){const p=effectivePrefs();appearanceRestoring=true;for(const k of ['theme','accent','experience'])$(k).value=p[k];$('compact').checked=p.compact;for(const[id,k]of [['cellFont','font'],['headerFont','header'],['rowPadding','row'],['colPadding','col']])$(id).value=p[k];$('fitColumns').value=p.fit??'content';applyAppearance();appearanceRestoring=false;}
$('applyLayout').onclick=action(()=>{const picked={font:+$('cellFont').value,header:+$('headerFont').value,row:+$('rowPadding').value,col:+$('colPadding').value,fit:$('fitColumns').value};if(picked.font<9||picked.font>24||picked.header<9||picked.header>24||picked.row<2||picked.row>24||picked.col<3||picked.col>40||Object.values(picked).slice(0,4).some(v=>!Number.isFinite(v)))throw Error('Use the displayed sizing ranges');if($('appearanceScope').value==='page')layoutPrefs.pages[appearanceTarget()]={...layoutPrefs.pages[appearanceTarget()],...picked};else layoutPrefs.app={...layoutPrefs.app,...picked};loadPagePrefs();persistSessionStore();});$('resetPageLayout').onclick=()=>{delete layoutPrefs.pages[appearanceTarget()];for(const id of Object.keys(layoutPrefs.panels))if(id.startsWith(appearanceTarget()+'-'))delete layoutPrefs.panels[id];$(appearanceTarget()).querySelectorAll('.panel').forEach(n=>{n.style.width='';n.style.height='';n.classList.remove('panel-maximized','panel-collapsed');});loadPagePrefs();};$('appearanceScope').onchange=()=>{loadPagePrefs();message('Appearance changes apply to '+$('appearanceScope').selectedOptions[0].text+'.');};$('exportLayout').onclick=()=>download('TuneLab-layout.json',JSON.stringify({format:'TuneLabLayout',preferences:layoutPrefs},null,2),'application/json');$('importLayout').onchange=action(async()=>{const file=$('importLayout').files[0];if(!file)return;const x=JSON.parse(await file.text());if(x.format!=='TuneLabLayout'||!x.preferences?.app)throw Error('Expected TuneLab layout preferences');layoutPrefs=x.preferences;loadPagePrefs();message('Appearance preferences imported.');});
function installPanels(){document.querySelectorAll('.page').forEach(page=>page.querySelectorAll('.panel').forEach((panel,j)=>{const id=page.id+'-'+j;panel.dataset.panelId=id;const controls=document.createElement('div');controls.className='panel-tools';controls.innerHTML='<button class="secondary" data-collapse-panel>Collapse</button><button class="secondary" data-max-panel>Expand</button>';panel.prepend(controls);panel.title='Resize using the bottom-right corner. Panel controls collapse or expand the workspace.';const saved=layoutPrefs.panels[id];if(saved){panel.style.width=saved.width??'';panel.style.height=saved.height??'';panel.classList.toggle('panel-collapsed',!!saved.collapsed);}controls.querySelector('[data-collapse-panel]').onclick=()=>{panel.classList.toggle('panel-collapsed');controls.querySelector('[data-collapse-panel]').textContent=panel.classList.contains('panel-collapsed')?'Open':'Collapse';savePanel(panel);};controls.querySelector('[data-max-panel]').onclick=()=>{panel.classList.toggle('panel-maximized');controls.querySelector('[data-max-panel]').textContent=panel.classList.contains('panel-maximized')?'Restore size':'Expand';};}));document.addEventListener('pointerup',()=>document.querySelectorAll('.page.active .panel[data-panel-id]').forEach(savePanel));}
