const platformControl=document.createElement('label');platformControl.innerHTML='Platform terminology<select id="platformMode"><option value="hondata">Hondata</option><option value="ktuner">KTuner</option></select>';document.querySelector('.preferences').prepend(platformControl);
function updateNames(){const platform=$('platformMode')?.value??'hondata',labels=platform==='hondata'?{mpr:'TC maximum pressure ratio',command:'TC Boost Command'}:{mpr:'Boost Target · related view',command:'Final Boost Target · related view'};document.querySelectorAll('[data-kind]').forEach(n=>{n.textContent=labels[n.dataset.kind];n.title=platform==='hondata'?'Related KTuner name: '+(n.dataset.kind==='mpr'?'Boost Target':'Final Boost Target')+' — relationship requires platform validation.':'Hondata source: '+(n.dataset.kind==='mpr'?'TC maximum pressure ratio':'TC Boost Command')+' — changing terminology does not change calibration provenance.';});$('boostAxisLabel').textContent=kind==='mpr'?'Atmospheric-pressure axis · bar':'Incoming command index · native display';}
$('platformMode').onchange=()=>{updateNames();message('Terminology view changed. Imported source identity and values are preserved.');};
addSection('compare','Platform compare',`<div class="panel"><h2>Compare platform pressure representations</h2><p>This view compares the loaded source numbers in Hondata absolute bar and KTuner matching PSI. It does not claim native ECU behavior or alter the source. Use Boost by gear for structural gear-table translation.</p><label>Source table<select id="compareTable"><option value="mpr">TC maximum pressure ratio / Boost Target</option><option value="command">TC Boost Command / Final Boost Target</option></select></label><button id="refreshCompare">Refresh comparison</button><div class="formrow"><div><h3>Hondata pressure representation · bar</h3><div id="compareHondata" class="table-scroll"></div></div><div><h3>KTuner pressure representation · matching PSI</h3><div id="compareKtuner" class="table-scroll"></div></div></div><p class="hint">MPR / Boost Target: documented related purpose. TC Boost Command / Final Boost Target: candidate relationship. Verify the selected platform, software version and native table axes. This representation comparison does not import a second platform calibration.</p><div id="compareSources"></div></div>`);
function renderCompare(){const k=$('compareTable').value,b=state[k],o=b.controls,bar={...clone(b.source),values:b.source.values.map(row=>row.map(v=>E.toBar(v,o.sourceUnits,+o.offset,+o.referencePa)))},psi={...clone(b.source),values:bar.values.map(row=>row.map(v=>W.pressure(v,'bar','ktuner',+o.referencePa,+o.offset)))};tableGrid('compareHondata',bar,false);tableGrid('compareKtuner',psi,false);$('compareSources').innerHTML=sourceLinks('hondata')+sourceLinks('ktuner');}
$('refreshCompare').onclick=renderCompare;$('compareTable').onchange=renderCompare;
function sourceLinks(platform){return '<ul>'+sources[platform].map(([name,url])=>`<li><a href="${url}" target="_blank" rel="noopener noreferrer">${esc(name)}</a></li>`).join('')+'</ul><p class="hint">Platform reference, not proof of every 11th-generation L15CA behavior. Hondata tuning notes above cover the 10th-generation turbo Civic; verify applicability. Links checked October 1, 2026.</p>';}
const pageHelp={boost:['Boost tables','Purpose: create a deliberate pressure-table proposal. Start by importing the table actually installed, checking body units, then choosing the region and gradual transition. Inspect the selected curve and changed cells before copying. TC maximum pressure ratio is Hondata’s official name for the main boost target; TC Boost Command has a separate role. Table values alone do not guarantee measured boost.'],afm:['Airflow calibration','Purpose: correct the installed airflow curve using matching warm, stable closed-loop evidence. Import the active curve, assign a baseline log, verify channels and units, then confirm the match. Inspect accepted samples, correction limits, and the editable two-row output. A separate validation log evaluates the proposal and never drives correction. Manual-only editing is available without a baseline.'],logs:['Historical-log review','Purpose: inspect actual versus requested boost in useful operating segments. Select a project log, choose a preset and segment, then click the plot or use the slider. The cursor, highlighted readings, histogram, scatter and operating markers share the filtered selection. Positive error means actual boost exceeds command at that instant. Gaps remain gaps. Filters cannot prove a control table was active.'],gears:['Boost-by-gear comparison','Purpose: preserve intentional per-gear limits while inspecting related targets. Import Hondata Gear × RPM or individual KTuner RPM × atmospheric-pressure tables. Choose reference atmospheric pressure and units. Translating Hondata to KTuner requires an explicit pressure strategy. Converting the other direction discards atmospheric variation; originals remain available.'],changes:['Change review','Purpose: inspect final differences from the source. Thresholds are personal review rules, not hardware safety limits. Absolute changes, eligible percentages and increased steps locate possible unintended edits. Edit History records individual operations and provides restoration controls. Actual boost and failure probability are not predicted.'],history:['Edit history','Purpose: trace individual changes to their table and coordinates. Show in table navigates to the first affected cell. Selective undo only proceeds when later edits have not changed the affected values, axes or controls. Restore revision returns the editing state to that point and records another operation; raw logs are not deleted.'],library:['Project log library','Purpose: import historical logs once and reuse them. Record installed calibration, conditions and notes. Active log is distinct from baseline/validation assignment. Exact duplicate CSV content is recognized. Learning records observations and eligibility; adding files does not validate outcomes. Save project JSON to preserve raw files and history independently of browser storage.'],project:['Project and revisions','Purpose: preserve the calibration context and work. v0.5 project files include raw historical CSVs, metadata, proposals, journal and learning entries. Reopening clears baseline/validation confirmations. Older v0.3/v0.4 projects are accepted. Do not mark a historical log as matching unless its installed calibration is known.'],compare:['Platform comparison','Purpose: compare source values using platform pressure representations. Names and units are explained separately from ECU behavior. This release converts the loaded source representation; it does not establish two calibrations are equivalent. Gear translation is available in Boost by gear.']};
function contextualHelp(key){const [title,text]=pageHelp[key]??pageHelp.boost;showHelp(title,text);$('helpBody').insertAdjacentHTML('beforeend',sourceLinks($('platformMode').value));}
$('openHelp').addEventListener('click',e=>{e.stopImmediatePropagation();contextualHelp(currentPage());},true);
document.addEventListener('click',e=>{const b=e.target.closest('.help-button');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const label=b.closest('label'),control=label?.querySelector('[id]'),key=control?.id;const item=help[key]??(key==='afmBandwidth'?help.afmbandwidth:null);if(item){showHelp(...item);$('helpBody').insertAdjacentHTML('beforeend',sourceLinks($('platformMode').value));}else{const heading=b.closest('h2')?.childNodes[0]?.textContent??label?.childNodes[0]?.textContent??'Workspace';showHelp(heading,(pageHelp[currentPage()]??pageHelp.boost)[1]);$('helpBody').insertAdjacentHTML('beforeend',sourceLinks($('platformMode').value));}},true);
const steps={boost:[['Load installed table','boostPaste','Paste the complete installed table with indices, or keep the existing source only if it matches.'],['Check units and region','sourceUnits','Confirm body units, then choose RPM and column regions.'],['Preview and refine','previewBoost','Calculate a proposal, inspect it, and make deliberate manual refinements.'],['Review and export','copyBoost','Use Change review to inspect differences, then copy the table in the destination units.']],afm:[['Load installed airflow curve','afmPaste','Import the curve used during the historical baseline log.'],['Assign historical evidence','baselineSession','Choose the baseline and check its calibration match, channels and units.'],['Analyze and inspect','analyzeAfm','Inspect coverage, correction cap, and the two-row proposed output.'],['Validate or export','validationSession','Assign an independent validation log if available; otherwise record that outcome is unvalidated.']],logs:[['Select a historical log','activeLog','Import logs once or select an existing session.'],['Choose meaningful data','logPreset','Use loaded acceleration for boost review, AFM eligibility for trim-oriented data, or raw for context.'],['Inspect a segment','logEvent','Choose a segment; move the cursor or slider to inspect simultaneous error.'],['Record an observation','recordInsight','Record a traceable analysis snapshot without asserting causation.']]};
let guideSteps={};
for(const[page,items]of Object.entries(steps)){const box=document.createElement('div');box.className='guide-workflow panel';box.innerHTML='<h2>Guided workflow</h2><div class="actions">'+items.map((x,j)=>`<button class="secondary" data-guide="${page}" data-step="${j}">${j+1}. ${esc(x[0])}</button>`).join('')+'</div><p data-guide-message>'+esc(items[0][2])+'</p>';$(page).prepend(box);box.addEventListener('click',e=>{const b=e.target.closest('[data-guide]');if(!b)return;document.querySelectorAll('.guide-focus').forEach(n=>n.classList.remove('guide-focus'));const item=items[+b.dataset.step],target=$(item[1]);if(target){for(let n=target.parentElement;n&&n!==$(page);n=n.parentElement)if(n.tagName==='DETAILS')n.open=true;target.classList.add('guide-focus');target.scrollIntoView?.({block:'center'});target.focus?.();}box.querySelector('[data-guide-message]').textContent=item[2];box.querySelectorAll('[data-guide]').forEach(n=>n.classList.toggle('active',n===b));guideSteps[page]=+b.dataset.step;});}
// Replace the global reveal toggle with explicit per-page options.
document.querySelectorAll('.preferences>button').forEach(n=>{if(n.textContent.includes('Show / hide advanced'))n.remove();});
for(const page of document.querySelectorAll('.page')){const details=[...page.querySelectorAll('.advanced-only')];if(!details.length)continue;const button=document.createElement('button');button.className='secondary options-toggle';button.textContent='Show advanced options';button.onclick=()=>{page.classList.toggle('showoptions');button.textContent=page.classList.contains('showoptions')?'Hide advanced options':'Show advanced options';};page.prepend(button);}
const insightButton=document.createElement('button');insightButton.id='recordInsight';insightButton.textContent='Record analysis insight';$('reviewLog').after(insightButton);insightButton.onclick=()=>{if(!sessionView||!activeSession){message('Select an imported session and analyze it first.','error');return;}const item=sessions.find(x=>x.id===activeSession);learning.push({sessionId:activeSession,date:new Date().toISOString(),title:'Filtered analysis snapshot',detail:`Preset ${$('logPreset').value}; ${sessionView.accepted} eligible samples, ${sessionView.rejected} excluded. Calibration: ${item.calibration||'unrecorded'}. Selection supports descriptive review only; independence, repeatability and outcome remain unvalidated.`,preset:$('logPreset').value});renderLearning();persistSessionStore();message('Review note saved with its limitations.');};
const autoLabel=document.createElement('label');autoLabel.innerHTML='Proposal preview<select id="autoPreview"><option value="auto">Automatic</option><option value="manual">Manual · Update proposal</option></select>';document.querySelector('.preferences').append(autoLabel);let autoTimer;
for(const id of boostIds.filter(x=>!['outputUnits','boostPrecision'].includes(x)))$(id).addEventListener('change',()=>{if($('autoPreview').value!=='auto')return;clearTimeout(autoTimer);autoTimer=setTimeout(()=>{if(state[kind].proposal?.manual){message('Controls changed. Manual refinements preserved; use Calculate proposal to review replacement.','dirty');return;}action(calculateBoost)();},300);});
$('previewBoost').textContent='Update proposal';
function activatePage(){loadPagePrefs();updateNames();if(currentPage()==='history')renderHistory();if(currentPage()==='library')rebuildSessionList();if(currentPage()==='compare')renderCompare();renderOverlays();}
document.querySelectorAll('[data-tab]').forEach(n=>{if(!['library','history','compare'].includes(n.dataset.tab))n.addEventListener('click',activatePage);});
const serializeV4=serialize;serialize=function(){return{...serializeV4(),version:5,sessionLibrary:sessionPayload()};};const loadV4=loadProject;loadProject=function(p){loadV4(p);restoreSessions(p.sessionLibrary);loadPagePrefs();renderBoost();renderAfm();renderHistory();};
// Persist session raw files when supported; project JSON is the portable backup.
try{const stored=JSON.parse(localStorage.getItem('TuneLabLayoutV5'));if(stored?.app)layoutPrefs=stored;}catch{}

Object.assign(help,{
activeLog:['Active historical log','Selects the raw session available to Log review and operating-location markers. It does not assign or confirm AFM baseline/validation roles.'],
baselineSession:['Baseline evidence session','Select the historical drive recorded with the currently imported airflow curve. Confirm separately only when calibration identity is known.'],validationSession:['Validation evidence session','Select an independent drive recorded with the proposed airflow curve. This does not create corrections; confirmation and coverage are required.'],comparisonSession:['Historical comparison','Overlays the selected second session’s actual boost after filtering. Time aligns segment starts; RPM aligns recorded engine speed. Conditions and calibration comparability are not established automatically.'],
logPreset:['Choose data suitable for your question','Loaded operation uses pedal threshold and positive command. Stable review additionally excludes large pedal changes. Spool/overshoot retains transitions. AFM eligibility uses AFM’s filters. Raw retains context within the selected RPM range.'],logEvent:['Choose one continuous operating segment','Segments split at excluded rows, gear changes, non-increasing time or gaps over 250 ms. A segment is a candidate pull; inspect whether it represents the intended maneuver.'],logPedal:['Loaded-operation pedal threshold','Accepts samples at or above this accelerator percentage when using loaded, steady or transient presets. It does not independently prove wide-open throttle or rising vehicle speed.'],logDelta:['Pedal stability threshold','Maximum pedal change between consecutive recorded samples for the steady preset. Other presets do not apply this threshold.'],logXAxis:['Chart horizontal axis','Time preserves event sequence. RPM helps compare curves at similar engine speeds but can revisit the same RPM more than once.'],logStart:['Visible time window start','Limits only the displayed boost plot. Eligibility and histogram/scatter analysis remain defined by preset and segment. Use Reset plot range to remove this zoom.'],logEnd:['Visible time window end','Ends the displayed time window. Slider inspection outside a complete configured window shifts it to reveal the selected point.'],logYMin:['Fixed boost-axis minimum','Enter a PSI minimum to prevent automatic scaling. Leave blank for automatic bounds, which include the comparison when both bounds are automatic.'],logYMax:['Fixed boost-axis maximum','Enter a PSI maximum; values beyond the bounds are clipped in the plot and still remain in the data. Leave blank to autoscale.'],
sourceRpm:['Source RPM breakpoints','Comma-separated increasing engine-speed indices. Preview resampling estimates the old table at these locations. New points outside the old range are blocked.'],sourceAxis:['Source column breakpoints','Uses the source table’s native column units. Protected coordinates must remain. Duplicate MPR endpoints require retaining the native column axis.'],
autoPreview:['Automatic or manual proposal updates','Automatic updates generated boost proposals after a short pause. Manual refinements pause automatic regeneration to prevent erasure. AFM analysis remains an explicit action.'],appearanceScope:['Appearance scope','Entire app updates defaults inherited by pages. This page creates an override. Reset removes an override; existing page overrides remain independent of default changes.'],cellFont:['Table value font size','Changes cell text only. It does not round values, change calculations, or alter export precision.'],headerFont:['Axis/header font size','Changes header text independently from body cells. Axis values remain unchanged.'],rowPadding:['Table row spacing','Changes space around table entries; smaller values show more rows. Compact mode limits spacing further.'],colPadding:['Table column spacing','Changes space beside values. Fit contents may scroll horizontally; fit width wraps long text.'],fitColumns:['Column layout','Fit contents preserves readable widths and scrolling. Fit available width distributes columns across the panel and may wrap long labels.']});
document.querySelectorAll('label').forEach(label=>{if(label.querySelector('.help-button'))return;const control=label.querySelector('input[id],select[id],textarea[id]');if(!control||control.type==='file')return;const b=document.createElement('button');b.type='button';b.className='help-button';b.textContent='?';b.setAttribute('aria-label','Explain '+(help[control.id]?.[0]??label.childNodes[0]?.textContent??control.id));label.append(b);});

