sessionDB().then(db=>{if(!db)return;const tx=db.transaction('projects','readonly'),req=tx.objectStore('projects').get('working');req.onsuccess=()=>{if(req.result&&!sessions.length&&!window.TuneLabProjectOpened){try{restoreSessions(req.result);loadPagePrefs();message('Historical session library restored from this browser. Load the matching calibration tables before correction.');}catch(e){message('Stored session restore failed: '+e.message,'error');}}};});
